/* h.rc - число мест (переменных, полей, элементов), где хранится список.
   Список - значение: если мест несколько, перед изменением делается копия.
   Список сам учитывает свои элементы: при добавлении элемент получает ещё
   одно место хранения, при удалении - теряет его. */
struct dl_LTSdelano { dan_hdr h; int64_t len, cap; dt_Sdelano *items; };

static void dl_LTSdelano_destroy(dan_hdr *h) {
    dl_LTSdelano *l = (dl_LTSdelano *)(void *)h;
    for (int64_t i = 0; i < l->len; i++) dt_Sdelano_release(l->items[i]);
    dan_free(l->items);
    dan_free(l);
}

static dl_LTSdelano *dl_LTSdelano_from(int64_t n, dt_Sdelano const *src) {
    dl_LTSdelano *l = dan_alloc(sizeof *l);
    dan_hdr_new(&l->h, dl_LTSdelano_destroy);
    l->len = n;
    l->cap = n < 4 ? 4 : n;
    l->items = dan_alloc((size_t)l->cap * sizeof(dt_Sdelano));
    for (int64_t i = 0; i < n; i++) l->items[i] = dt_Sdelano_share(src[i]);
    return l;
}

static void dl_LTSdelano_push(dl_LTSdelano *l, dt_Sdelano v) {
    if (l->len == l->cap) {
        l->cap *= 2;
        l->items = dan_realloc(l->items, (size_t)l->cap * sizeof(dt_Sdelano));
    }
    l->items[l->len++] = dt_Sdelano_share(v);
}

static dt_Sdelano dl_LTSdelano_get(const dl_LTSdelano *l, int64_t i, int line) {
    if (i < 0 || i >= l->len) dan_index_error(i, l->len, line);
    return l->items[i];
}

static dt_Sdelano *dl_LTSdelano_at(dl_LTSdelano *l, int64_t i, int line) {
    if (i < 0 || i >= l->len) dan_index_error(i, l->len, line);
    return &l->items[i];
}

static void dl_LTSdelano_set(dl_LTSdelano *l, int64_t i, dt_Sdelano v, int line) {
    if (i < 0 || i >= l->len) dan_index_error(i, l->len, line);
    dt_Sdelano old = l->items[i];
    l->items[i] = dt_Sdelano_share(v);
    dt_Sdelano_release(old);
    (void)old;
}

static void dl_LTSdelano_write(const dl_LTSdelano *l) {
    putchar('[');
    for (int64_t i = 0; i < l->len; i++) {
        if (i) fputs(", ", stdout);
        dt_Sdelano_write(l->items[i]);
    }
    putchar(']');
}

static void dl_LTSdelano_insert(dl_LTSdelano *l, int64_t i, dt_Sdelano v, int line) {
    if (i < 0 || i > l->len) dan_index_error(i, l->len, line);
    dl_LTSdelano_push(l, v);
    dt_Sdelano last = l->items[l->len - 1];
    memmove(&l->items[i + 1], &l->items[i], (size_t)(l->len - 1 - i) * sizeof(dt_Sdelano));
    l->items[i] = last;
}

static void dl_LTSdelano_remove(dl_LTSdelano *l, int64_t i, int line) {
    if (i < 0 || i >= l->len) dan_index_error(i, l->len, line);
    dt_Sdelano old = l->items[i];
    memmove(&l->items[i], &l->items[i + 1], (size_t)(l->len - i - 1) * sizeof(dt_Sdelano));
    l->len--;
    dt_Sdelano_release(old);
    (void)old;
}

/* новый список с теми же элементами; элементы получают ещё одно место хранения */
static dl_LTSdelano *dl_LTSdelano_copy(const dl_LTSdelano *l) {
    return dl_LTSdelano_from(l->len, l->items);
}

static inline dl_LTSdelano *dl_LTSdelano_share(dl_LTSdelano *l) { if (l) dan_hdr_share(&l->h); return l; }
static inline void dl_LTSdelano_release(dl_LTSdelano *l) { if (l) dan_hdr_release(&l->h, dl_LTSdelano_destroy); }
static inline void dl_LTSdelano_give(dl_LTSdelano *l) { if (l) dan_hdr_give(&l->h, dl_LTSdelano_destroy); }

/* место *pp собирается изменить список: если список хранится и в других
   местах, место получает собственную копию */
static dl_LTSdelano *dl_LTSdelano_mut(dl_LTSdelano **pp) {
    dl_LTSdelano *l = *pp;
    if (l->h.rc > 1) {
        dl_LTSdelano *r = dl_LTSdelano_copy(l);
        r->h.rc = 1;
        l->h.rc--;
        *pp = r;
        return r;
    }
    return l;
}

static dl_LTSdelano *dl_LTSdelano_reversed(const dl_LTSdelano *l) {
    dl_LTSdelano *r = dl_LTSdelano_copy(l);
    for (int64_t i = 0, j = r->len - 1; i < j; i++, j--) { dt_Sdelano t = r->items[i]; r->items[i] = r->items[j]; r->items[j] = t; }
    return r;
}

/* elements a..b inclusive; b == a - 1 gives an empty list */
static dl_LTSdelano *dl_LTSdelano_slice(const dl_LTSdelano *l, int64_t a, int64_t b, int line) {
    if (a < 0 || a > l->len) dan_index_error(a, l->len, line);
    if (b < a - 1 || b >= l->len) dan_index_error(b, l->len, line);
    return dl_LTSdelano_from(b - a + 1, l->items + a);
}

static dan_str dl_LTSdelano_str(const dl_LTSdelano *l) {
    dan_buf b = { NULL, 0, 0 };
    dan_buf_add(&b, "[");
    for (int64_t i = 0; i < l->len; i++) {
        if (i) dan_buf_add(&b, ", ");
        dan_buf_add(&b, dt_Sdelano_str(l->items[i]));
    }
    dan_buf_add(&b, "]");
    return dan_buf_str(&b);
}


static int64_t dl_LTSdelano_find(const dl_LTSdelano *l, dt_Sdelano b) {
    for (int64_t i = 0; i < l->len; i++) { dt_Sdelano a = l->items[i]; if (dt_Sdelano_eq(a, b)) return i; }
    return -1;
}
static bool dl_LTSdelano_contains(const dl_LTSdelano *l, dt_Sdelano b) { return dl_LTSdelano_find(l, b) >= 0; }
static bool dl_LTSdelano_eq(const dl_LTSdelano *x, const dl_LTSdelano *y) {
    if (x->len != y->len) return false;
    for (int64_t i = 0; i < x->len; i++) { dt_Sdelano a = x->items[i]; dt_Sdelano b = y->items[i]; if (!(dt_Sdelano_eq(a, b))) return false; }
    return true;
}


